  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useRef, useState } from "react";
 24→import { toast } from "sonner";
 25→import { useWebSocket } from "@/hooks/use-websocket";
 26→import {
 27→  initNotifications,
 28→  isNotificationsEnabled,
 29→  setNotificationsEnabled,
 30→  requestPermission,
 31→} from "@/lib/notifications";
 32→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 33→import { Chat } from "@/components/dashboard/chat";
 34→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 35→import { DiffsPanel } from "@/components/dashboard/diffs-panel";
 36→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 37→import { SfxSettings } from "@/components/dashboard/sfx-settings";
 38→import { Toaster } from "@/components/ui/sonner";
 39→import { TooltipProvider } from "@/components/ui/tooltip";
 40→import { cn } from "@/lib/utils";
 41→
 42→export default function DashboardPage() {
 43→  const {
 44→    connected,
 45→    initialLoadDone,
 46→    historyLoading,
 47→    agents,
 48→    agentOrder,
 49→    activeAgentId,
 50→    setActiveAgentId,
 51→    activeStatus,
 52→    activeMessages,
 53→    activeRawMessages,
 54→    activeModel,
 55→    spawnAgent,
 56→    sendMessage,
 57→    respondToControl,
 58→    respondToUserQuestion,
 59→    killAgent,
 60→    deleteAgent,
 61→    renameAgent,
 62→    clearHistory,
 63→    pinAgent,
 64→    iceboxAgent,
 65→    moveAgent,
 66→    tasks,
 67→    createTask,
 68→    updateTask,
 69→    deleteTask,
 70→    delegateTask,
 71→    workspaces,
 72→    activeWorkspaceId,
 73→    setActiveWorkspaceId,
 74→    createWorkspace,
 75→    renameWorkspace,
 76→    deleteWorkspace,
 77→    browseDirectory,
 78→    directoryListing,
 79→    notifications,
 80→    clearNotifications,
 81→    dismissNotification,
 82→    markNotificationRead,
 83→  } = useWebSocket();
 84→
 85→  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
 86→  const [showDiffs, setShowDiffs] = useState(false);
 87→  const [sidebarOpen, setSidebarOpen] = useState(false);
 88→  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
 89→  const [sfxSettingsOpen, setSfxSettingsOpen] = useState(false);
 90→  const [selectedModel, setSelectedModel] = useState("");
 91→  const [notificationsEnabled, setNotificationsEnabledState] = useState(false);
 92→
 93→  // Initialize notifications on mount
 94→  useEffect(() => {
 95→    initNotifications();
 96→    setNotificationsEnabledState(isNotificationsEnabled());
 97→  }, []);
 98→
 99→  const handleToggleNotifications = async () => {
100→    if (!notificationsEnabled) {
101→      // Enabling: request permission first if needed
102→      const granted = await requestPermission();
103→      if (!granted && typeof window !== "undefined" && "Notification" in window && Notification.permission === "denied") {
104→        toast.error("Notifications blocked — enable in browser settings");
105→        return;
106→      }
107→    }
108→    const next = !notificationsEnabled;
109→    setNotificationsEnabled(next);
110→    setNotificationsEnabledState(next);
111→  };
112→
113→  // Derive initial path from first workspace or fallback to "/"
114→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
115→
116→  // Connection status toasts (skip initial connection)
117→  const hasConnectedRef = useRef(false);
118→  useEffect(() => {
119→    if (connected) {
120→      if (hasConnectedRef.current) {
121→        toast.success("Reconnected");
122→      }
123→      hasConnectedRef.current = true;
124→    } else if (hasConnectedRef.current) {
125→      toast.error("Connection lost");
126→    }
127→  }, [connected]);
128→
129→  useEffect(() => {
130→    document.title = "thos — dashboard";
131→  }, []);
132→
133→  return (
134→    <TooltipProvider delayDuration={300}>
135→    <div className="relative flex h-dvh overflow-hidden">
136→      {/* Sidebar backdrop (mobile only) */}
137→      {sidebarOpen && (
138→        <div
139→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
140→          onClick={() => setSidebarOpen(false)}
141→        />
142→      )}
143→
144→      {/* Sidebar drawer */}
145→      <div
146→        className={cn(
147→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
148→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
149→        )}
150→      >
151→        <AgentSidebar
152→          agents={agents}
153→          agentOrder={agentOrder}
154→          activeAgentId={activeAgentId}
155→          loading={!initialLoadDone}
156→          onSelect={(id) => {
157→            setActiveAgentId(id);
158→            setSidebarOpen(false);
159→          }}
160→          onNewAgent={() => {
161→            setActiveAgentId(null);
162→            setSidebarOpen(false);
163→          }}
164→          onKill={killAgent}
165→          onDelete={deleteAgent}
166→          onRename={renameAgent}
167→          onClearHistory={clearHistory}
168→          onPin={pinAgent}
169→          onIcebox={iceboxAgent}
170→          onMoveAgent={moveAgent}
171→          workspaces={workspaces}
172→          activeWorkspaceId={activeWorkspaceId}
173→          onSelectWorkspace={setActiveWorkspaceId}
174→          onRenameWorkspace={renameWorkspace}
175→          onDeleteWorkspace={deleteWorkspace}
176→          onOpenFolder={() => setFolderBrowserOpen(true)}
177→        />
178→      </div>
179→
180→      {/* Main chat area (hidden in board mode) */}
181→      <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
182→        <Chat
183→          connected={connected}
184→          loading={!initialLoadDone || historyLoading}
185→          status={activeStatus}
186→          agentLabel={activeAgentId ? agents.get(activeAgentId)?.label : null}
187→          messages={activeMessages}
188→          rawMessages={activeRawMessages}
189→          activeModel={activeModel}
190→          selectedModel={selectedModel}
191→          onModelChange={setSelectedModel}
192→          onSendMessage={sendMessage}
193→          onSpawnAgent={(prompt) => spawnAgent(prompt, selectedModel || undefined)}
194→          onRespondToControl={respondToControl}
195→          onRespondToUserQuestion={respondToUserQuestion}
196→          onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
197→          showTasks={taskView !== "hidden"}
198→          onToggleTasks={() => setTaskView((v) => (v === "hidden" ? "list" : "hidden"))}
199→          showDiffs={showDiffs}
200→          onToggleDiffs={() => setShowDiffs((v) => !v)}
201→          onToggleSidebar={() => setSidebarOpen((v) => !v)}
202→          onOpenSfxSettings={() => setSfxSettingsOpen(true)}
203→          notificationsEnabled={notificationsEnabled}
204→          onToggleNotifications={handleToggleNotifications}
205→          notifications={notifications}
206→          onSelectNotification={(agentId, notifId) => {
207→            setActiveAgentId(agentId);
208→            markNotificationRead(notifId);
209→          }}
210→          onDismissNotification={dismissNotification}
211→          onClearNotifications={clearNotifications}
212→        />
213→      </div>
214→
215→      {/* Task panel backdrop (mobile only) */}
216→      {taskView !== "hidden" && (
217→        <div
218→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
219→          onClick={() => setTaskView("hidden")}
220→        />
221→      )}
222→
223→      {/* Task panel drawer */}
224→      {taskView !== "hidden" && (
225→        <div
226→          className={cn(
227→            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
228→            taskView === "board"
229→              ? "w-full max-w-none"
230→              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
231→          )}
232→        >
233→          <TaskPanel
234→            tasks={tasks}
235→            mode={taskView}
236→            onModeChange={(mode) => setTaskView(mode)}
237→            onCreateTask={createTask}
238→            onUpdateTask={updateTask}
239→            onDeleteTask={deleteTask}
240→            onDelegateTask={delegateTask}
241→            onSelectAgent={(agentId) => {
242→              setActiveAgentId(agentId);
243→            }}
244→            onClose={() => setTaskView("hidden")}
245→          />
246→        </div>
247→      )}
248→
249→      {/* Diffs panel backdrop (mobile only) */}
250→      {showDiffs && (
251→        <div
252→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
253→          onClick={() => setShowDiffs(false)}
254→        />
255→      )}
256→
257→      {/* Diffs panel drawer */}
258→      {showDiffs && (
259→        <div className="fixed inset-y-0 right-0 z-50 w-96 max-w-[calc(100vw-3rem)] md:max-w-none border-l bg-background flex flex-col min-w-0 md:relative md:z-auto">
260→          <DiffsPanel
261→            messages={activeMessages}
262→            onSendMessage={sendMessage}
263→            onClose={() => setShowDiffs(false)}
264→          />
265→        </div>
266→      )}
267→
268→      {/* SFX settings modal */}
269→      <SfxSettings
270→        open={sfxSettingsOpen}
271→        onClose={() => setSfxSettingsOpen(false)}
272→      />
273→
274→      {/* Folder browser modal */}
275→      <FolderBrowser
276→        open={folderBrowserOpen}
277→        onClose={() => setFolderBrowserOpen(false)}
278→        directoryListing={directoryListing}
279→        onBrowse={browseDirectory}
280→        onCreate={(name, cwd) => {
281→          createWorkspace(name, cwd);
282→          setFolderBrowserOpen(false);
283→        }}
284→        initialPath={initialBrowsePath}
285→      />
286→
287→      <Toaster />
288→    </div>
289→    </TooltipProvider>
290→  );
291→}
