  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { createPortal } from "react-dom";
 17→import { EllipsisVertical, Pin, Snowflake, Plus, ChevronRight } from "lucide-react";
 18→import type { AgentStatus, Workspace } from "@/lib/types";
 19→import type { AgentClientState } from "@/hooks/use-websocket";
 20→import { Tip } from "@/components/ui/tip";
 21→import { cn } from "@/lib/utils";
 22→import { WorkspaceSwitcher } from "./workspace-switcher";
 23→
 24→/** Status dot color + optional pulse animation. */
 25→const STATUS_DOT: Record<AgentStatus, string> = {
 26→  idle: "bg-muted-foreground",
 27→  spawning: "bg-yellow-500 animate-pulse",
 28→  connected: "bg-green-500",
 29→  thinking: "bg-blue-500 animate-pulse",
 30→  done: "bg-muted-foreground",
 31→  disconnected: "bg-orange-500 animate-pulse",
 32→  error: "bg-red-500",
 33→};
 34→
 35→/** Statuses where the CLI is actively running and can be killed. */
 36→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 37→/** Statuses considered archived (session ended, read-only). */
 38→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 39→
 40→interface ContextMenuState {
 41→  agentId: string;
 42→  x: number;
 43→  y: number;
 44→}
 45→
 46→export function AgentSidebar({
 47→  agents,
 48→  agentOrder,
 49→  activeAgentId,
 50→  loading,
 51→  onSelect,
 52→  onNewAgent,
 53→  onKill,
 54→  onDelete,
 55→  onRename,
 56→  onClearHistory,
 57→  onPin,
 58→  onIcebox,
 59→  onMoveAgent,
 60→  workspaces,
 61→  activeWorkspaceId,
 62→  onSelectWorkspace,
 63→  onRenameWorkspace,
 64→  onDeleteWorkspace,
 65→  onOpenFolder,
 66→}: {
 67→  agents: Map<string, AgentClientState>;
 68→  agentOrder: string[];
 69→  activeAgentId: string | null;
 70→  loading?: boolean;
 71→  onSelect: (agentId: string | null) => void;
 72→  onNewAgent: () => void;
 73→  onKill: (agentId: string) => void;
 74→  onDelete: (agentId: string) => void;
 75→  onRename: (agentId: string, label: string) => void;
 76→  onClearHistory: (agentId: string) => void;
 77→  onPin: (agentId: string, pinned: boolean) => void;
 78→  onIcebox: (agentId: string, iceboxed: boolean) => void;
 79→  onMoveAgent: (agentId: string, workspaceId: string | null) => void;
 80→  workspaces: Workspace[];
 81→  activeWorkspaceId: string | null;
 82→  onSelectWorkspace: (workspaceId: string | null) => void;
 83→  onRenameWorkspace: (workspaceId: string, name: string) => void;
 84→  onDeleteWorkspace: (workspaceId: string) => void;
 85→  onOpenFolder: () => void;
 86→}) {
 87→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 88→  const [renamingId, setRenamingId] = useState<string | null>(null);
 89→  const menuRef = useRef<HTMLDivElement>(null);
 90→
 91→  // Sort helper: most recent first by createdAt
 92→  const byRecency = (a: string, b: string) => {
 93→    const ca = agents.get(a)?.createdAt ?? 0;
 94→    const cb = agents.get(b)?.createdAt ?? 0;
 95→    return cb - ca;
 96→  };
 97→
 98→  // Split agents into pinned, active, icebox, and archived
 99→  const pinnedIds = agentOrder
100→    .filter((id) => {
101→      const a = agents.get(id);
102→      return a && a.pinned && !a.iceboxed;
103→    })
104→    .sort(byRecency);
105→  const activeIds = agentOrder
106→    .filter((id) => {
107→      const a = agents.get(id);
108→      return a && !a.pinned && !a.iceboxed && !ARCHIVED.has(a.status);
109→    })
110→    .sort(byRecency);
111→  const iceboxIds = agentOrder
112→    .filter((id) => {
113→      const a = agents.get(id);
114→      return a && a.iceboxed;
115→    })
116→    .sort(byRecency);
117→  const archivedIds = agentOrder
118→    .filter((id) => {
119→      const a = agents.get(id);
120→      return a && !a.pinned && !a.iceboxed && ARCHIVED.has(a.status);
121→    })
122→    .sort(byRecency);
123→
124→  // Close context menu on click-outside or Escape
125→  useEffect(() => {
126→    if (!ctxMenu) return;
127→    function handleClick(e: MouseEvent) {
128→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
129→        setCtxMenu(null);
130→      }
131→    }
132→    function handleKey(e: KeyboardEvent) {
133→      if (e.key === "Escape") setCtxMenu(null);
134→    }
135→    document.addEventListener("mousedown", handleClick);
136→    document.addEventListener("keydown", handleKey);
137→    return () => {
138→      document.removeEventListener("mousedown", handleClick);
139→      document.removeEventListener("keydown", handleKey);
140→    };
141→  }, [ctxMenu]);
142→
143→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
144→    setCtxMenu({ agentId, x, y });
145→  }, []);
146→
147→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
148→    e.preventDefault();
149→    openMenu(agentId, e.clientX, e.clientY);
150→  }, [openMenu]);
151→
152→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
153→    e.stopPropagation();
154→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
155→    openMenu(agentId, rect.right, rect.bottom);
156→  }, [openMenu]);
157→
158→  const closeMenu = useCallback(() => setCtxMenu(null), []);
159→
160→  function renderAgentRow(id: string, dimmed: boolean) {
161→    const agent = agents.get(id);
162→    if (!agent) return null;
163→    const isActive = id === activeAgentId;
164→    return (
165→      <div
166→        key={id}
167→        onClick={() => onSelect(id)}
168→        onContextMenu={(e) => handleContextMenu(e, id)}
169→        className={cn(
170→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
171→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
172→          dimmed && "opacity-60"
173→        )}
174→      >
175→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
176→          <span className="flex items-center gap-2">
177→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
178→            {renamingId === id ? (
179→              <RenameInput
180→                initialValue={agent.label}
181→                onConfirm={(label) => {
182→                  onRename(id, label);
183→                  setRenamingId(null);
184→                }}
185→                onCancel={() => setRenamingId(null)}
186→              />
187→            ) : (
188→              <Tip text={agent.label || "new agent"} side="right"><span className="truncate">{agent.label || "new agent"}</span></Tip>
189→            )}
190→            {agent.pinned && (
191→              <Pin className="size-2.5 shrink-0 text-muted-foreground" />
192→            )}
193→            {agent.iceboxed && (
194→              <Snowflake className="size-2.5 shrink-0 text-muted-foreground" />
195→            )}
196→          </span>
197→          <span className="pl-4 text-[10px] text-muted-foreground truncate font-mono">
198→            {id}
199→            {(() => {
200→              const ws = workspaces.find((w) => w.id === agent.workspaceId);
201→              return ws ? <span className="opacity-60"> · {ws.name}</span> : null;
202→            })()}
203→          </span>
204→        </div>
205→        <button
206→          onClick={(e) => handleMenuButton(e, id)}
207→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
208→          aria-label="Agent menu"
209→        >
210→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
211→        </button>
212→      </div>
213→    );
214→  }
215→
216→  return (
217→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
218→      {/* Workspace switcher */}
219→      <div className="border-b">
220→        <WorkspaceSwitcher
221→          workspaces={workspaces}
222→          activeWorkspaceId={activeWorkspaceId}
223→          onSelect={onSelectWorkspace}
224→          onRename={onRenameWorkspace}
225→          onDelete={onDeleteWorkspace}
226→          onOpenFolder={onOpenFolder}
227→        />
228→      </div>
229→
230→      {/* Header */}
231→      <div className="flex items-center justify-between px-3 py-2">
232→        <span className="text-xs font-semibold">agents</span>
233→        <button
234→          onClick={onNewAgent}
235→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
236→          aria-label="New agent"
237→        >
238→          <Plus className="size-3.5" />
239→        </button>
240→      </div>
241→
242→      {/* Agent list */}
243→      <div className="flex-1 overflow-y-auto">
244→        {loading ? (
245→          <div className="space-y-1 px-3 py-2">
246→            {[...Array(4)].map((_, i) => (
247→              <div key={i} className="flex items-center gap-2 py-2">
248→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
249→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
250→              </div>
251→            ))}
252→          </div>
253→        ) : agentOrder.length === 0 ? (
254→          <div className="px-3 py-4 text-xs text-muted-foreground">
255→            No agents yet
256→          </div>
257→        ) : null}
258→
259→        {/* Pinned agents */}
260→        {pinnedIds.length > 0 && (
261→          <>
262→            <div className="flex items-center gap-2 px-3 pt-2 pb-1">
263→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">pinned</span>
264→              <div className="flex-1 border-t" />
265→            </div>
266→            {pinnedIds.map((id) => renderAgentRow(id, false))}
267→          </>
268→        )}
269→
270→        {/* Active agents */}
271→        {activeIds.length > 0 && (
272→          <>
273→            {pinnedIds.length > 0 && (
274→              <div className="flex items-center gap-2 px-3 pt-3 pb-1">
275→                <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">active</span>
276→                <div className="flex-1 border-t" />
277→              </div>
278→            )}
279→            {activeIds.map((id) => renderAgentRow(id, false))}
280→          </>
281→        )}
282→
283→        {/* Icebox agents */}
284→        {iceboxIds.length > 0 && (
285→          <>
286→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
287→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">icebox</span>
288→              <div className="flex-1 border-t" />
289→            </div>
290→            {iceboxIds.map((id) => renderAgentRow(id, true))}
291→          </>
292→        )}
293→
294→        {/* Archived divider + agents */}
295→        {archivedIds.length > 0 && (
296→          <>
297→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
298→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
299→              <div className="flex-1 border-t" />
300→            </div>
301→            {archivedIds.map((id) => renderAgentRow(id, true))}
302→          </>
303→        )}
304→      </div>
305→
306→      {/* Context menu — portaled to body to escape sidebar stacking context */}
307→      {ctxMenu && (() => {
308→        const agent = agents.get(ctxMenu.agentId);
309→        if (!agent) return null;
310→        return createPortal(
311→          <div
312→            ref={menuRef}
313→            className="fixed z-[9999] min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
314→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
315→          >
316→            <ContextMenuItem
317→              label={agent.pinned ? "Unpin" : "Pin"}
318→              onClick={() => {
319→                onPin(ctxMenu.agentId, !agent.pinned);
320→                closeMenu();
321→              }}
322→            />
323→            <ContextMenuItem
324→              label={agent.iceboxed ? "Un-icebox" : "Icebox"}
325→              onClick={() => {
326→                onIcebox(ctxMenu.agentId, !agent.iceboxed);
327→                closeMenu();
328→              }}
329→            />
330→            {workspaces.length > 0 && (
331→              <ContextMenuSub label="Move to…">
332→                {workspaces
333→                  .filter((w) => w.id !== agent.workspaceId)
334→                  .map((w) => (
335→                    <ContextMenuItem
336→                      key={w.id}
337→                      label={w.name}
338→                      onClick={() => {
339→                        onMoveAgent(ctxMenu.agentId, w.id);
340→                        closeMenu();
341→                      }}
342→                    />
343→                  ))}
344→                {agent.workspaceId && (
345→                  <>
346→                    <div className="my-1 border-t" />
347→                    <ContextMenuItem
348→                      label="No workspace"
349→                      onClick={() => {
350→                        onMoveAgent(ctxMenu.agentId, null);
351→                        closeMenu();
352→                      }}
353→                    />
354→                  </>
355→                )}
356→              </ContextMenuSub>
357→            )}
358→            <ContextMenuItem
359→              label="Rename"
360→              onClick={() => {
361→                setRenamingId(ctxMenu.agentId);
362→                closeMenu();
363→              }}
364→            />
365→            {KILLABLE.has(agent.status) && (
366→              <ContextMenuItem
367→                label="Kill"
368→                onClick={() => {
369→                  onKill(ctxMenu.agentId);
370→                  closeMenu();
371→                }}
372→              />
373→            )}
374→            <ContextMenuItem
375→              label="Clear History"
376→              onClick={() => {
377→                onClearHistory(ctxMenu.agentId);
378→                closeMenu();
379→              }}
380→            />
381→            <div className="my-1 border-t" />
382→            <ContextMenuItem
383→              label="Delete"
384→              destructive
385→              onClick={() => {
386→                closeMenu();
387→                if (confirm("Delete this agent? This cannot be undone.")) {
388→                  onDelete(ctxMenu.agentId);
389→                }
390→              }}
391→            />
392→          </div>,
393→          document.body
394→        );
395→      })()}
396→    </div>
397→  );
398→}
