 3→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 4→function isAllowedIP(ip: string): boolean {
 5→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 6→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 7→  const parts = addr.split(".");
 8→  if (parts.length !== 4) return false;
 9→  const first = parseInt(parts[0], 10);
10→  const second = parseInt(parts[1], 10);
11→  return first === 100 && second >= 64 && second <= 127;
12→}
13→
14→export function middleware(req: NextRequest) {
15→  const ip = (req as NextRequest & { ip?: string }).ip ?? req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ?? "";
16→  if (!ip || isAllowedIP(ip)) return NextResponse.next();
17→  return new NextResponse("Forbidden", { status: 403 });
18→}
