129→/**
130→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
131→ * Used both for live messages and for replaying message_history.
132→ */
133→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
134→  if (relayMsg.type === "relay") {
135→    const msg = relayMsg.message;
136→
137→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
138→      const init = msg as ClaudeSystemInit;
139→      return {
140→        id: nextId(),
141→        role: "system",
142→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
143→        timestamp: Date.now(),
144→      };
145→    }
146→
147→    if (msg.type === "user") {
148→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
149→      // Only render human-typed user messages (string content).
150→      // CLI tool_result messages have array content — these are internal
151→      // protocol messages and are only visible in the raw message viewer.
152→      if (typeof rawContent !== "string") return null;
153→      if (!rawContent.trim()) return null;
154→      return {
155→        id: nextId(),
156→        role: "user",
157→        content: rawContent,
158→        timestamp: Date.now(),
159→      };
160→    }
161→
162→    if (msg.type === "assistant") {
163→      const assistant = msg as ClaudeAssistant;
164→      const text = extractText(assistant);
165→      if (!text) return null;
166→
167→      const blocks = assistant.message?.content ?? [];
168→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
169→
170→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
171→      const resultMap = new Map<string, string>();
172→      for (const b of blocks) {
173→        if (b.type === "tool_result") {
174→          const tr = b as { tool_use_id?: string; content?: unknown };
175→          if (tr.tool_use_id) {
176→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
177→            const firstLine = raw.split("\n")[0];
178→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
179→          }
180→        }
181→      }
182→
183→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
184→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
185→      // DiffViewer can render syntax-highlighted before/after diffs. Other
186→      // tools only keep the name and result preview to avoid carrying
187→      // unnecessary data (e.g. Read file contents, Bash output).
188→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
189→      const toolCalls: ToolCallInfo[] = blocks
190→        .filter((b) => b.type === "tool_use")
191→        .map((b) => {
192→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
193→          const info: ToolCallInfo = {
194→            name: tu.name,
195→            toolUseId: tu.id,
196→            resultPreview: resultMap.get(tu.id),
197→          };
198→          if (DIFF_TOOLS.has(tu.name)) {
199→            info.input = tu.input;
200→          }
201→          return info;
202→        });
203→      const isToolOnly = !hasText && toolCalls.length > 0;
204→
205→      return {
206→        id: nextId(),
207→        role: "assistant",
208→        content: text,
209→        timestamp: Date.now(),
210→        toolCalls,
211→        isToolOnly,
212→      };
213→    }
214→
215→    if (msg.type === "result") {
216→      const result = msg as ClaudeResult;
217→      const summary = result.is_error
218→        ? `Error: ${result.error}`
219→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
220→      return {
221→        id: nextId(),
222→        role: "system",
223→        content: summary,
224→        timestamp: Date.now(),
225→      };
226→    }
227→
228→    if (msg.type === "control_request") {
229→      const cr = msg as ClaudeControlRequest;
230→
231→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
232→      if (cr.request.tool_name === "AskUserQuestion") {
233→        const input = cr.request.input as { questions?: UserQuestion[] };
234→        const questions = Array.isArray(input.questions) ? input.questions : [];
235→        return {
236→          id: nextId(),
237→          role: "system",
238→          content: "Question from Claude",
239→          timestamp: Date.now(),
240→          userQuestion: {
241→            requestId: cr.request_id,
242→            questions,
243→          },
244→        };
245→      }
246→
247→      return {
248→        id: nextId(),
249→        role: "system",
250→        content: `Tool approval requested: ${cr.request.tool_name}`,
251→        timestamp: Date.now(),
252→        controlRequest: {
253→          id: cr.request_id,
254→          tool_name: cr.request.tool_name,
255→          input: cr.request.input,
256→          description: cr.request.description,
257→        },
258→      };
259→    }
260→  }
261→
262→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
263→    return {
264→      id: nextId(),
265→      role: "system",
266→      content: `Error: ${relayMsg.error}`,
267→      timestamp: Date.now(),
268→    };
269→  }
270→
271→  return null;
272→}
