930→  const activeModel = activeAgent?.model ?? null;
931→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
932→
933→  // ── Notification inbox actions ──────────────────────────────────────────
934→
935→  const clearNotifications = useCallback(() => {
