951→    initialLoadDone,
952→    historyLoading,
953→    agents,
954→    agentOrder,
955→    activeAgentId,
956→    setActiveAgentId,
957→    activeStatus,
958→    activeMessages,
959→    activeRawMessages,
960→    activeModel,
961→    spawnAgent,
962→    sendMessage,
963→    respondToControl,
964→    respondToUserQuestion,
965→    killAgent,
966→    deleteAgent,
967→    renameAgent,
968→    clearHistory,
969→    pinAgent,
970→    iceboxAgent,
971→    moveAgent,
972→    tasks,
973→    createTask,
974→    updateTask,
975→    deleteTask,
976→    delegateTask,
977→    workspaces,
978→    activeWorkspaceId,
979→    setActiveWorkspaceId,
980→    createWorkspace,
981→    renameWorkspace,
982→    deleteWorkspace,
983→    browseDirectory,
984→    directoryListing,
985→    notifications,
986→    clearNotifications,
987→    dismissNotification,
988→    markNotificationRead,
989→  };
990→}
