  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  DirectoryEntry,
 55→  NotificationItem,
 56→  NotificationType,
 57→  ServerMessage,
 58→  ServerMessageHistory,
 59→  ServerTaskList,
 60→  ServerTaskUpdated,
 61→  ServerTaskDeleted,
 62→  Task,
 63→  TaskPriority,
 64→  ToolCallInfo,
 65→  UserQuestion,
 66→  Workspace,
 67→} from "@/lib/types";
 68→import { sfxTool, sfxDone, sfxError, sfxQuestion, sfxBegin, sfxSend } from "@/lib/sfx";
 69→import {
 70→  notifyDone,
 71→  notifyError,
 72→  notifyControlRequest,
 73→  notifyQuestion,
 74→} from "@/lib/notifications";
 75→
 76→/** Connect to the WS server on the same host the page was loaded from. */
 77→const WS_URL =
 78→  typeof window !== "undefined"
 79→    ? `ws://${window.location.hostname}:9900/browser`
 80→    : "ws://localhost:9900/browser";
 81→
 82→/** Per-agent client state. */
 83→export interface AgentClientState {
 84→  status: AgentStatus;
 85→  messages: ChatMessage[];
 86→  /** Raw Claude NDJSON messages for debug view. */
 87→  rawMessages: ClaudeMessage[];
 88→  label: string;
 89→  tmuxSession: string | null;
 90→  createdAt: number;
 91→  /** Model name from system/init or agent_list. */
 92→  model?: string;
 93→  /** Whether this agent is pinned to the top of the sidebar. */
 94→  pinned?: boolean;
 95→  /** Whether this agent is in the icebox. */
 96→  iceboxed?: boolean;
 97→  /** Workspace this agent belongs to. */
 98→  workspaceId?: string | null;
 99→}
100→
101→/**
102→ * Extract displayable text from a Claude assistant message.
103→ * Content blocks may be text, tool_use, or tool_result — each is
104→ * handled defensively since the array structure can vary.
105→ */
106→function extractText(msg: ClaudeAssistant): string {
107→  const blocks = msg.message?.content;
108→  if (!blocks || !Array.isArray(blocks)) return "";
109→  return blocks
110→    .map((b) => {
111→      if (b.type === "text") return b.text;
112→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
113→      if (b.type === "tool_result") {
114→        const c = (b as { content?: unknown }).content;
115→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
116→      }
117→      return "";
118→    })
119→    .filter(Boolean)
120→    .join("\n");
121→}
122→
123→/** Module-level counter for generating unique message IDs. */
124→let msgCounter = 0;
125→function nextId() {
126→  return `msg-${Date.now()}-${++msgCounter}`;
127→}
128→
129→/**
130→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
131→ * Used both for live messages and for replaying message_history.
132→ */
133→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
134→  if (relayMsg.type === "relay") {
135→    const msg = relayMsg.message;
136→
137→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
138→      const init = msg as ClaudeSystemInit;
139→      return {
140→        id: nextId(),
141→        role: "system",
142→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
143→        timestamp: Date.now(),
144→      };
145→    }
146→
147→    if (msg.type === "user") {
148→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
149→      // Only render human-typed user messages (string content).
150→      // CLI tool_result messages have array content — these are internal
151→      // protocol messages and are only visible in the raw message viewer.
152→      if (typeof rawContent !== "string") return null;
153→      if (!rawContent.trim()) return null;
154→      return {
155→        id: nextId(),
156→        role: "user",
157→        content: rawContent,
158→        timestamp: Date.now(),
159→      };
160→    }
161→
162→    if (msg.type === "assistant") {
163→      const assistant = msg as ClaudeAssistant;
164→      const text = extractText(assistant);
165→      if (!text) return null;
166→
167→      const blocks = assistant.message?.content ?? [];
168→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
169→
170→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
171→      const resultMap = new Map<string, string>();
172→      for (const b of blocks) {
173→        if (b.type === "tool_result") {
174→          const tr = b as { tool_use_id?: string; content?: unknown };
175→          if (tr.tool_use_id) {
176→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
177→            const firstLine = raw.split("\n")[0];
178→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
179→          }
180→        }
181→      }
182→
183→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
184→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
185→      // DiffViewer can render syntax-highlighted before/after diffs. Other
186→      // tools only keep the name and result preview to avoid carrying
187→      // unnecessary data (e.g. Read file contents, Bash output).
188→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
189→      const toolCalls: ToolCallInfo[] = blocks
190→        .filter((b) => b.type === "tool_use")
191→        .map((b) => {
192→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
193→          const info: ToolCallInfo = {
194→            name: tu.name,
195→            toolUseId: tu.id,
196→            resultPreview: resultMap.get(tu.id),
197→          };
198→          if (DIFF_TOOLS.has(tu.name)) {
199→            info.input = tu.input;
200→          }
201→          return info;
202→        });
203→      const isToolOnly = !hasText && toolCalls.length > 0;
204→
205→      return {
206→        id: nextId(),
207→        role: "assistant",
208→        content: text,
209→        timestamp: Date.now(),
210→        toolCalls,
211→        isToolOnly,
212→      };
213→    }
214→
215→    if (msg.type === "result") {
216→      const result = msg as ClaudeResult;
217→      const summary = result.is_error
218→        ? `Error: ${result.error}`
219→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
220→      return {
221→        id: nextId(),
222→        role: "system",
223→        content: summary,
224→        timestamp: Date.now(),
225→      };
226→    }
227→
228→    if (msg.type === "control_request") {
229→      const cr = msg as ClaudeControlRequest;
230→
231→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
232→      if (cr.request.tool_name === "AskUserQuestion") {
233→        const input = cr.request.input as { questions?: UserQuestion[] };
234→        const questions = Array.isArray(input.questions) ? input.questions : [];
235→        return {
236→          id: nextId(),
237→          role: "system",
238→          content: "Question from Claude",
239→          timestamp: Date.now(),
240→          userQuestion: {
241→            requestId: cr.request_id,
242→            questions,
243→          },
244→        };
245→      }
246→
247→      return {
248→        id: nextId(),
249→        role: "system",
250→        content: `Tool approval requested: ${cr.request.tool_name}`,
251→        timestamp: Date.now(),
252→        controlRequest: {
253→          id: cr.request_id,
254→          tool_name: cr.request.tool_name,
255→          input: cr.request.input,
256→          description: cr.request.description,
257→        },
258→      };
259→    }
260→  }
261→
262→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
263→    return {
264→      id: nextId(),
265→      role: "system",
266→      content: `Error: ${relayMsg.error}`,
267→      timestamp: Date.now(),
268→    };
269→  }
270→
271→  return null;
272→}
273→
274→/** Console logger with [thos] prefix for easy filtering. */
275→function log(...args: unknown[]) {
276→  console.log("[thos-ws]", ...args);
277→}
278→
279→export function useWebSocket() {
280→  const wsRef = useRef<WebSocket | null>(null);
281→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
282→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
283→  const closingRef = useRef(false);
284→  const [connected, setConnected] = useState(false);
285→  /** True once we've received the initial agent_list from the server. */
286→  const [initialLoadDone, setInitialLoadDone] = useState(false);
287→
288→  // Multi-agent state
289→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
290→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
291→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
292→
293→  // Task state
294→  const [tasks, setTasks] = useState<Task[]>([]);
295→
296→  // Workspace state
297→  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
298→  const [activeWorkspaceId, setActiveWorkspaceIdState] = useState<string | null>(null);
299→  const [directoryListing, setDirectoryListing] = useState<{ path: string; entries: DirectoryEntry[] } | null>(null);
300→
301→  // Notification inbox state
302→  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
303→  let notifCounter = useRef(0);
304→
305→  // Refs for accessing current state inside the onmessage closure.
306→  const activeAgentIdRef = useRef(activeAgentId);
307→  activeAgentIdRef.current = activeAgentId;
308→  const agentsRef = useRef(agents);
309→  agentsRef.current = agents;
310→
311→  // Per-agent deduplication: track count of processed messages per agent
312→  // to avoid duplicating messages already in local state during history replay.
313→  const processedCountRef = useRef<Map<string, number>>(new Map());
314→
315→  // Track which agents have had their history loaded (lazy loading).
316→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
317→
318→  /** Immutably update a single agent's state in the Map. */
319→  const updateAgent = useCallback(
320→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
321→      setAgents((prev) => {
322→        const existing = prev.get(agentId);
323→        if (!existing) return prev;
324→        const next = new Map(prev);
325→        next.set(agentId, updater(existing));
326→        return next;
327→      });
328→    },
329→    []
330→  );
331→
332→  /** Build notification options for an agent event. */
333→  const notifyOpts = (agentId: string) => {
334→    const agent = agentsRef.current.get(agentId);
335→    return {
336→      agentId,
337→      agentLabel: agent?.label || agentId.slice(0, 8),
338→      isActiveAgent: agentId === activeAgentIdRef.current,
339→    };
340→  };
341→
342→  /** Push a notification item to the inbox. */
343→  const pushNotification = (type: NotificationType, agentId: string, message: string) => {
344→    const agent = agentsRef.current.get(agentId);
345→    const item: NotificationItem = {
346→      id: `notif-${Date.now()}-${++notifCounter.current}`,
347→      type,
348→      agentId,
349→      agentLabel: agent?.label || agentId.slice(0, 8),
350→      message,
351→      timestamp: Date.now(),
352→      read: false,
353→    };
354→    setNotifications((prev) => [item, ...prev]);
355→  };
356→
357→  const connect = useCallback(() => {
358→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
359→    if (wsRef.current) {
360→      wsRef.current.close();
361→      wsRef.current = null;
362→    }
363→
364→    // Reset dedup counts on new connection — server will send fresh history
365→    processedCountRef.current.clear();
366→    setInitialLoadDone(false);
367→    setLoadedAgents(new Set());
368→
369→    log("connecting to", WS_URL);
370→    const ws = new WebSocket(WS_URL);
371→    wsRef.current = ws;
372→
373→    ws.onopen = () => {
374→      log("connected");
375→      setConnected(true);
376→    };
377→
378→    ws.onclose = () => {
379→      log("disconnected, closingRef =", closingRef.current);
380→      setConnected(false);
381→      wsRef.current = null;
382→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
383→      if (closingRef.current) return;
384→      // Reconnection guard: clear any existing timer before scheduling
385→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
386→      log("scheduling reconnect in 2s");
387→      reconnectTimer.current = setTimeout(() => connect(), 2000);
388→    };
389→
390→    ws.onerror = (e) => {
391→      log("error", e);
392→      // onclose will fire after onerror, which triggers reconnect
393→    };
394→
395→    ws.onmessage = (event) => {
396→      let data: ServerMessage;
397→      try {
398→        data = JSON.parse(event.data as string);
399→      } catch {
400→        return;
401→      }
402→
403→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
404→
405→      // ── workspace_list: full workspace list from server ──
406→      if (data.type === "workspace_list") {
407→        const wsList = (data as { workspaces: Workspace[] }).workspaces;
408→        log("workspace_list:", wsList.length, "workspaces");
409→        setWorkspaces(wsList);
410→        return;
411→      }
412→
413→      // ── directory_listing: response to browse_directory ──
414→      if (data.type === "directory_listing") {
415→        const listing = data as { path: string; entries: DirectoryEntry[] };
416→        log("directory_listing:", listing.path, listing.entries.length, "entries");
417→        setDirectoryListing({ path: listing.path, entries: listing.entries });
418→        return;
419→      }
420→
421→      // ── task_list: full task list from server ──
422→      if (data.type === "task_list") {
423→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
424→        setTasks((data as ServerTaskList).tasks);
425→        return;
426→      }
427→
428→      // ── task_updated: single task changed ──
429→      if (data.type === "task_updated") {
430→        const updated = (data as ServerTaskUpdated).task;
431→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
432→        return;
433→      }
434→
435→      // ── task_deleted: remove task ──
436→      if (data.type === "task_deleted") {
437→        const deletedId = (data as ServerTaskDeleted).taskId;
438→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
439→        return;
440→      }
441→
442→      // ── message_history: replay full history from server ──
443→      if (data.type === "message_history") {
444→        const historyMsg = data as ServerMessageHistory;
445→        const agentId = historyMsg.agentId;
446→        const serverMessages = historyMsg.messages;
447→        log("message_history:", agentId, serverMessages.length, "raw msgs");
448→
449→        // Convert all server messages to ChatMessages + extract raw Claude messages
450→        const chatMessages: ChatMessage[] = [];
451→        const rawMessages: ClaudeMessage[] = [];
452→        for (const sm of serverMessages) {
453→          if (sm.type === "relay") {
454→            rawMessages.push(sm.message);
455→          }
456→          const cm = relayChatMessage(agentId, sm);
457→          if (cm) chatMessages.push(cm);
458→        }
459→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
460→
461→        // Always replace local messages with server history (source of truth).
462→        setAgents((prev) => {
463→          const existing = prev.get(agentId);
464→          if (!existing) {
465→            log("message_history:", agentId, "agent not in map yet, creating");
466→            const next = new Map(prev);
467→            next.set(agentId, {
468→              status: "idle",
469→              messages: chatMessages,
470→              rawMessages,
471→              label: "",
472→              tmuxSession: null,
473→              createdAt: 0,
474→            });
475→            return next;
476→          }
477→          const next = new Map(prev);
478→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
479→          return next;
480→        });
481→
482→        processedCountRef.current.set(agentId, chatMessages.length);
483→        setLoadedAgents((prev) => {
484→          if (prev.has(agentId)) return prev;
485→          const next = new Set(prev);
486→          next.add(agentId);
487→          return next;
488→        });
489→        return;
490→      }
491→
492→      // ── history_cleared: wipe local messages for this agent ──
493→      if (data.type === "history_cleared") {
494→        updateAgent(data.agentId, (prev) => ({
495→          ...prev,
496→          messages: [],
497→          rawMessages: [],
498→        }));
499→        processedCountRef.current.set(data.agentId, 0);
500→        return;
501→      }
502→
503→      // ── cli_disconnected: show system message ──
504→      if (data.type === "cli_disconnected") {
505→        updateAgent(data.agentId, (prev) => ({
506→          ...prev,
507→          messages: [
508→            ...prev.messages,
509→            {
510→              id: nextId(),
511→              role: "system",
512→              content: "CLI session ended",
513→              timestamp: Date.now(),
514→            },
515→          ],
516→        }));
517→        return;
518→      }
519→
520→      // ── cli_connected: show system message ──
521→      if (data.type === "cli_connected") {
522→        updateAgent(data.agentId, (prev) => ({
523→          ...prev,
524→          messages: [
525→            ...prev.messages,
526→            {
527→              id: nextId(),
528→              role: "system",
529→              content: "CLI reconnected",
530→              timestamp: Date.now(),
531→            },
532→          ],
533→        }));
534→        return;
535→      }
536→
537→      // ── agent_list: reconcile sidebar state from server ──
538→      if (data.type === "agent_list") {
539→        const serverAgents = data.agents as AgentInfo[];
540→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
541→        setAgents((prev) => {
542→          const next = new Map(prev);
543→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
544→
545→          // Update or add agents from server
546→          for (const info of serverAgents) {
547→            const existing = next.get(info.agentId);
548→            if (existing) {
549→              next.set(info.agentId, {
550→                ...existing,
551→                status: info.status,
552→                tmuxSession: info.tmuxSession,
553→                label: info.label,
554→                model: info.model ?? existing.model,
555→                pinned: info.pinned ?? false,
556→                iceboxed: info.iceboxed ?? false,
557→                workspaceId: info.workspaceId,
558→              });
559→            } else {
560→              next.set(info.agentId, {
561→                status: info.status,
562→                messages: [],
563→                rawMessages: [],
564→                label: info.label,
565→                tmuxSession: info.tmuxSession,
566→                createdAt: info.createdAt,
567→                model: info.model ?? undefined,
568→                pinned: info.pinned ?? false,
569→                iceboxed: info.iceboxed ?? false,
570→                workspaceId: info.workspaceId,
571→              });
572→            }
573→          }
574→
575→          // Remove agents no longer on the server
576→          for (const id of next.keys()) {
577→            if (!serverIds.has(id)) {
578→              next.delete(id);
579→            }
580→          }
581→
582→          return next;
583→        });
584→        setAgentOrder(serverAgents.map((a) => a.agentId));
585→        setInitialLoadDone(true);
586→
587→        // Auto-select the first agent on initial load when nothing is selected
588→        setActiveAgentId((prev) => {
589→          if (prev !== null) return prev;
590→          if (serverAgents.length === 0) return null;
591→          return serverAgents[0].agentId;
592→        });
593→        return;
594→      }
595→
596→      // ── spawned: auto-select the newly created agent ──
597→      if (data.type === "spawned") {
598→        setActiveAgentId(data.agentId);
599→        return;
600→      }
601→
602→      // ── status: update a specific agent's status ──
603→      if (data.type === "status") {
604→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
605→        return;
606→      }
607→
608→      // ── error: append to agent's message list ──
609→      if (data.type === "error") {
610→        sfxError();
611→        updateAgent(data.agentId, (prev) => ({
612→          ...prev,
613→          messages: [
614→            ...prev.messages,
615→            {
616→              id: nextId(),
617→              role: "system",
618→              content: `Error: ${data.error}`,
619→              timestamp: Date.now(),
620→            },
621→          ],
622→        }));
623→        // Track processed count for dedup
624→        processedCountRef.current.set(
625→          data.agentId,
626→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
627→        );
628→        return;
629→      }
630→
631→      // ── relay: append claude message to agent's history ──
632→      if (data.type === "relay") {
633→        const agentId = data.agentId;
634→        const rawMsg = data.message;
635→        const chatMsg = relayChatMessage(agentId, data);
636→
637→        // SFX: play a sound for each tool call in the message
638→        if (chatMsg?.toolCalls?.length) {
639→          // Play SFX for the first mapped tool (avoids overlapping sounds in multi-tool messages)
640→          const first = chatMsg.toolCalls.find((tc) => tc.name);
641→          if (first) sfxTool(first.name);
642→        }
643→
644→        // SFX + notifications: result done / error
645→        if (rawMsg.type === "result") {
646→          const result = rawMsg as ClaudeResult;
647→          if (result.is_error) {
648→            sfxError();
649→            notifyError(notifyOpts(agentId));
650→            pushNotification("error", agentId, "Agent error");
651→          } else {
652→            sfxDone();
653→            notifyDone(notifyOpts(agentId));
654→            pushNotification("done", agentId, "Agent finished");
655→          }
656→        }
657→
658→        // SFX + notifications: control request (tool approval / question)
659→        if (rawMsg.type === "control_request") {
660→          sfxQuestion();
661→          const cr = rawMsg as ClaudeControlRequest;
662→          if (cr.request.tool_name === "AskUserQuestion") {
663→            notifyQuestion(notifyOpts(agentId));
664→            pushNotification("question", agentId, "Question from agent");
665→          } else {
666→            notifyControlRequest({
667→              ...notifyOpts(agentId),
668→              toolName: cr.request.tool_name,
669→            });
670→            pushNotification("control_request", agentId, `Approval needed: ${cr.request.tool_name}`);
671→          }
672→        }
673→
674→        // SFX: session start
675→        if (rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init") {
676→          sfxBegin();
677→        }
678→
679→        // Capture model from system/init
680→        const initModel =
681→          rawMsg.type === "system" && (rawMsg as { subtype?: string }).subtype === "init"
682→            ? (rawMsg as ClaudeSystemInit).model
683→            : undefined;
684→
685→        updateAgent(agentId, (prev) => ({
686→          ...prev,
687→          rawMessages: [...prev.rawMessages, rawMsg],
688→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
689→          ...(initModel ? { model: initModel } : {}),
690→        }));
691→        if (chatMsg) {
692→          // Track processed count for dedup
693→          processedCountRef.current.set(
694→            agentId,
695→            (processedCountRef.current.get(agentId) ?? 0) + 1
696→          );
697→        }
698→        return;
699→      }
700→    };
701→  }, [updateAgent]);
702→
703→  useEffect(() => {
704→    closingRef.current = false;
705→    connect();
706→    return () => {
707→      closingRef.current = true;
708→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
709→      wsRef.current?.close();
710→    };
711→  }, [connect]);
712→
713→  const send = useCallback((data: object) => {
714→    if (wsRef.current?.readyState === WebSocket.OPEN) {
715→      wsRef.current.send(JSON.stringify(data));
716→    }
717→  }, []);
718→
719→  // Request history for the active agent if not already loaded.
720→  useEffect(() => {
721→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
722→    log("requesting history for", activeAgentId);
723→    send({ type: "request_history", agentId: activeAgentId });
724→  }, [activeAgentId, loadedAgents, send]);
725→
726→  const spawnAgent = useCallback(
727→    (prompt: string, model?: string) => {
728→      send({ type: "spawn", prompt, ...(model ? { model } : {}) });
729→    },
730→    [send]
731→  );
732→
733→  const sendMessage = useCallback(
734→    (content: string) => {
735→      if (!activeAgentId) return;
736→      // Optimistically add user message to local state
737→      updateAgent(activeAgentId, (prev) => ({
738→        ...prev,
739→        messages: [
740→          ...prev.messages,
741→          {
742→            id: nextId(),
743→            role: "user",
744→            content,
745→            timestamp: Date.now(),
746→          },
747→        ],
748→      }));
749→      send({ type: "send_message", agentId: activeAgentId, content });
750→      sfxSend();
751→    },
752→    [send, activeAgentId, updateAgent]
753→  );
754→
755→  const respondToControl = useCallback(
756→    (requestId: string, allow: boolean) => {
757→      if (!activeAgentId) return;
