762→          m.controlRequest?.id === requestId
763→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true, allowed: allow } }
764→            : m
765→        ),
766→      }));
767→    },
768→    [send, activeAgentId, updateAgent]
769→  );
770→
771→  /** Respond to an AskUserQuestion control request with the user's selections. */
772→  const respondToUserQuestion = useCallback(
