822→    },
823→    [send]
824→  );
825→
826→  const pinAgent = useCallback(
827→    (agentId: string, pinned: boolean) => {
828→      send({ type: "pin_agent", agentId, pinned });
829→    },
830→    [send]
831→  );
832→
833→  const iceboxAgent = useCallback(
