  1→"use client";
  2→
  3→/**
  4→ * Dashboard route (`/dashboard`).
  5→ *
  6→ * Orchestrates the multi-agent WebSocket hook, sidebar, chat panel, and
  7→ * task panel. Clicking "+" or selecting "New Agent" sets `activeAgentId`
  8→ * to `null`, which shows the spawn input. On spawn, the server responds
  9→ * with `spawned` and the hook auto-selects the new agent.
 10→ *
 11→ * ## Loading states
 12→ *
 13→ * Two loading flags from the hook control the UI:
 14→ * - `initialLoadDone` — false until the first `agent_list` arrives from
 15→ *   the server. While false, the sidebar shows skeleton rows.
 16→ * - `historyLoading` — true when the active agent's message history has
 17→ *   not been fetched yet (lazy loading). The chat shows a "Loading
 18→ *   messages..." indicator until the server responds.
 19→ *
 20→ * Sidebar uses `!initialLoadDone`, chat uses `!initialLoadDone || historyLoading`.
 21→ */
 22→
 23→import { useEffect, useRef, useState } from "react";
 24→import { toast } from "sonner";
 25→import { useWebSocket } from "@/hooks/use-websocket";
 26→import {
 27→  initNotifications,
 28→  isNotificationsEnabled,
 29→  setNotificationsEnabled,
 30→  requestPermission,
 31→} from "@/lib/notifications";
 32→import { AgentSidebar } from "@/components/dashboard/agent-sidebar";
 33→import { Chat } from "@/components/dashboard/chat";
 34→import { TaskPanel, type TaskViewMode } from "@/components/dashboard/kanban-board";
 35→import { DiffsPanel } from "@/components/dashboard/diffs-panel";
 36→import { FolderBrowser } from "@/components/dashboard/folder-browser";
 37→import { SfxSettings } from "@/components/dashboard/sfx-settings";
 38→import { Toaster } from "@/components/ui/sonner";
 39→import { TooltipProvider } from "@/components/ui/tooltip";
 40→import { cn } from "@/lib/utils";
 41→
 42→export default function DashboardPage() {
 43→  const {
 44→    connected,
 45→    initialLoadDone,
 46→    historyLoading,
 47→    agents,
 48→    agentOrder,
 49→    activeAgentId,
 50→    setActiveAgentId,
 51→    activeStatus,
 52→    activeMessages,
 53→    activeRawMessages,
 54→    activeModel,
 55→    spawnAgent,
 56→    sendMessage,
 57→    respondToControl,
 58→    respondToUserQuestion,
 59→    killAgent,
 60→    deleteAgent,
 61→    renameAgent,
 62→    clearHistory,
 63→    pinAgent,
 64→    iceboxAgent,
 65→    moveAgent,
 66→    tasks,
 67→    createTask,
 68→    updateTask,
 69→    deleteTask,
 70→    delegateTask,
 71→    workspaces,
 72→    activeWorkspaceId,
 73→    setActiveWorkspaceId,
 74→    createWorkspace,
 75→    renameWorkspace,
 76→    deleteWorkspace,
 77→    browseDirectory,
 78→    directoryListing,
 79→    notifications,
 80→    clearNotifications,
 81→    dismissNotification,
 82→    markNotificationRead,
 83→    testNotification,
 84→  } = useWebSocket();
 85→
 86→  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
 87→  const [showDiffs, setShowDiffs] = useState(false);
 88→  const [sidebarOpen, setSidebarOpen] = useState(false);
 89→  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
 90→  const [sfxSettingsOpen, setSfxSettingsOpen] = useState(false);
 91→  const [selectedModel, setSelectedModel] = useState("");
 92→  const [notificationsEnabled, setNotificationsEnabledState] = useState(false);
 93→
 94→  // Initialize notifications on mount
 95→  useEffect(() => {
 96→    initNotifications();
 97→    setNotificationsEnabledState(isNotificationsEnabled());
 98→  }, []);
 99→
100→  const handleToggleNotifications = async () => {
101→    if (!notificationsEnabled) {
102→      // Enabling: request permission first if needed
103→      const granted = await requestPermission();
104→      if (!granted && typeof window !== "undefined" && "Notification" in window && Notification.permission === "denied") {
105→        toast.error("Notifications blocked — enable in browser settings");
106→        return;
107→      }
108→    }
109→    const next = !notificationsEnabled;
110→    setNotificationsEnabled(next);
111→    setNotificationsEnabledState(next);
112→  };
113→
114→  // Derive initial path from first workspace or fallback to "/"
115→  const initialBrowsePath = workspaces.length > 0 ? workspaces[0].cwd : "/";
116→
117→  // Connection status toasts (skip initial connection)
118→  const hasConnectedRef = useRef(false);
119→  useEffect(() => {
120→    if (connected) {
121→      if (hasConnectedRef.current) {
122→        toast.success("Reconnected");
123→      }
124→      hasConnectedRef.current = true;
125→    } else if (hasConnectedRef.current) {
126→      toast.error("Connection lost");
127→    }
128→  }, [connected]);
129→
130→  useEffect(() => {
131→    document.title = "thos — dashboard";
132→  }, []);
133→
134→  return (
135→    <TooltipProvider delayDuration={300}>
136→    <div className="relative flex h-dvh overflow-hidden">
137→      {/* Sidebar backdrop (mobile only) */}
138→      {sidebarOpen && (
139→        <div
140→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
141→          onClick={() => setSidebarOpen(false)}
142→        />
143→      )}
144→
145→      {/* Sidebar drawer */}
146→      <div
147→        className={cn(
148→          "fixed inset-y-0 left-0 z-50 w-56 transition-transform duration-200 ease-in-out md:relative md:z-auto md:translate-x-0 md:transition-none",
149→          sidebarOpen ? "translate-x-0" : "-translate-x-full"
150→        )}
151→      >
152→        <AgentSidebar
153→          agents={agents}
154→          agentOrder={agentOrder}
155→          activeAgentId={activeAgentId}
156→          loading={!initialLoadDone}
157→          onSelect={(id) => {
158→            setActiveAgentId(id);
159→            setSidebarOpen(false);
160→          }}
161→          onNewAgent={() => {
162→            setActiveAgentId(null);
163→            setSidebarOpen(false);
164→          }}
165→          onKill={killAgent}
166→          onDelete={deleteAgent}
167→          onRename={renameAgent}
168→          onClearHistory={clearHistory}
169→          onPin={pinAgent}
170→          onIcebox={iceboxAgent}
171→          onMoveAgent={moveAgent}
172→          workspaces={workspaces}
173→          activeWorkspaceId={activeWorkspaceId}
174→          onSelectWorkspace={setActiveWorkspaceId}
175→          onRenameWorkspace={renameWorkspace}
176→          onDeleteWorkspace={deleteWorkspace}
177→          onOpenFolder={() => setFolderBrowserOpen(true)}
178→        />
179→      </div>
180→
181→      {/* Main chat area (hidden in board mode) */}
182→      <div className={cn("flex min-w-0 flex-1 flex-col", taskView === "board" && "hidden")}>
183→        <Chat
184→          connected={connected}
185→          loading={!initialLoadDone || historyLoading}
186→          status={activeStatus}
187→          agentLabel={activeAgentId ? agents.get(activeAgentId)?.label : null}
188→          messages={activeMessages}
189→          rawMessages={activeRawMessages}
190→          activeModel={activeModel}
191→          selectedModel={selectedModel}
192→          onModelChange={setSelectedModel}
193→          onSendMessage={sendMessage}
194→          onSpawnAgent={(prompt) => spawnAgent(prompt, selectedModel || undefined)}
195→          onRespondToControl={respondToControl}
196→          onRespondToUserQuestion={respondToUserQuestion}
197→          onClearHistory={() => { if (activeAgentId) clearHistory(activeAgentId); }}
198→          showTasks={taskView !== "hidden"}
199→          onToggleTasks={() => setTaskView((v) => (v === "hidden" ? "list" : "hidden"))}
200→          showDiffs={showDiffs}
201→          onToggleDiffs={() => setShowDiffs((v) => !v)}
202→          onToggleSidebar={() => setSidebarOpen((v) => !v)}
203→          onOpenSfxSettings={() => setSfxSettingsOpen(true)}
204→          notificationsEnabled={notificationsEnabled}
205→          onToggleNotifications={handleToggleNotifications}
206→          notifications={notifications}
207→          onSelectNotification={(agentId, notifId) => {
208→            setActiveAgentId(agentId);
209→            markNotificationRead(notifId);
210→          }}
211→          onDismissNotification={dismissNotification}
212→          onClearNotifications={clearNotifications}
213→          onTestNotification={testNotification}
214→        />
215→      </div>
216→
217→      {/* Task panel backdrop (mobile only) */}
218→      {taskView !== "hidden" && (
219→        <div
220→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
221→          onClick={() => setTaskView("hidden")}
222→        />
223→      )}
224→
225→      {/* Task panel drawer */}
226→      {taskView !== "hidden" && (
227→        <div
228→          className={cn(
229→            "fixed inset-y-0 right-0 z-50 border-l bg-background flex flex-col min-w-0 md:relative md:z-auto",
230→            taskView === "board"
231→              ? "w-full max-w-none"
232→              : "w-80 max-w-[calc(100vw-3rem)] md:max-w-none"
233→          )}
234→        >
235→          <TaskPanel
236→            tasks={tasks}
237→            mode={taskView}
238→            onModeChange={(mode) => setTaskView(mode)}
239→            onCreateTask={createTask}
240→            onUpdateTask={updateTask}
241→            onDeleteTask={deleteTask}
242→            onDelegateTask={delegateTask}
243→            onSelectAgent={(agentId) => {
244→              setActiveAgentId(agentId);
245→            }}
246→            onClose={() => setTaskView("hidden")}
247→          />
248→        </div>
249→      )}
250→
251→      {/* Diffs panel backdrop (mobile only) */}
252→      {showDiffs && (
253→        <div
254→          className="fixed inset-0 z-40 bg-black/50 md:hidden"
255→          onClick={() => setShowDiffs(false)}
256→        />
257→      )}
258→
259→      {/* Diffs panel drawer */}
260→      {showDiffs && (
261→        <div className="fixed inset-y-0 right-0 z-50 w-96 max-w-[calc(100vw-3rem)] md:max-w-none border-l bg-background flex flex-col min-w-0 md:relative md:z-auto">
262→          <DiffsPanel
263→            messages={activeMessages}
264→            onSendMessage={sendMessage}
265→            onClose={() => setShowDiffs(false)}
266→          />
267→        </div>
268→      )}
269→
270→      {/* SFX settings modal */}
271→      <SfxSettings
272→        open={sfxSettingsOpen}
273→        onClose={() => setSfxSettingsOpen(false)}
274→      />
275→
276→      {/* Folder browser modal */}
277→      <FolderBrowser
278→        open={folderBrowserOpen}
279→        onClose={() => setFolderBrowserOpen(false)}
280→        directoryListing={directoryListing}
281→        onBrowse={browseDirectory}
282→        onCreate={(name, cwd) => {
283→          createWorkspace(name, cwd);
284→          setFolderBrowserOpen(false);
285→        }}
286→        initialPath={initialBrowsePath}
287→      />
288→
289→      <Toaster />
290→    </div>
291→    </TooltipProvider>
292→  );
293→}
