import { TooltipProvider } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

export default function DashboardPage() {
  const {
    connected,
    initialLoadDone,
    historyLoading,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    activeModel,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    pinAgent,
    iceboxAgent,
    moveAgent,
    tasks,
    createTask,
    updateTask,
    deleteTask,
    delegateTask,
    workspaces,
    activeWorkspaceId,
    setActiveWorkspaceId,
    createWorkspace,
    renameWorkspace,
    deleteWorkspace,
    browseDirectory,
    directoryListing,
    notifications,
    clearNotifications,
    dismissNotification,
    markNotificationRead,
    testNotification,
  } = useWebSocket();

  const [taskView, setTaskView] = useState<"hidden" | TaskViewMode>("hidden");
  const [showDiffs, setShowDiffs] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [folderBrowserOpen, setFolderBrowserOpen] = useState(false);
  const [sfxSettingsOpen, setSfxSettingsOpen] = useState(false);
  const [selectedModel, setSelectedModel] = useState("");
  const [notificationsEnabled, setNotificationsEnabledState] = useState(false);

